const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const toshkaLakes = ee.Geometry.Rectangle([30.5, 22.5, 32.5, 24.5]);

  // Time periods for comparison
  const period1 = {start: '2002-09-01', end: '2002-09-30'};
  const period2 = {start: '2012-06-01', end: '2012-06-30'};

  // 2. Data Acquisition - Using Landsat for better historical coverage
  function getWaterCollection(startDate, endDate) {
    return ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(toshkaLakes)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 20));
  }

  const col2002 = getWaterCollection(period1.start, period1.end);
  const col2012 = getWaterCollection(period2.start, period2.end);

  // Check collection sizes
  const count2002 = col2002.size().getInfo();
  const count2012 = col2012.size().getInfo();

  console.log(`2002 Images: ${count2002}`);
  console.log(`2012 Images: ${count2012}`);

  if (count2002 === 0 || count2012 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create water masks using NDWI
  function createWaterMask(image) {
    // Calculate NDWI
    const ndwi = image.normalizedDifference(['SR_B2', 'SR_B5']).rename('NDWI');

    // Water threshold (NDWI > 0.2 for water)
    const waterMask = ndwi.gt(0.2);

    // Apply scaling factor for Landsat 7
    return waterMask.multiply(image.select('SR_B1').gt(0));
  }

  // Get median composites
  const water2002 = col2002.map(createWaterMask).median();
  const water2012 = col2012.map(createWaterMask).median();

  // 4. Calculation - Count water pixels
  function countWaterPixels(image) {
    return image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: toshkaLakes,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    }).get('NDWI').getInfo();
  }

  const pixels2002 = countWaterPixels(water2002);
  const pixels2012 = countWaterPixels(water2012);

  console.log(`2002 Water Pixels: ${pixels2002}`);
  console.log(`2012 Water Pixels: ${pixels2012}`);

  // 5. Validation & Final Answer
  if (pixels2002 === 0 || pixels2012 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (pixels2002 === null || pixels2012 === null || 
      isNaN(pixels2002) || isNaN(pixels2012)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if 2012 has fewer water pixels than 2002
  const decrease = pixels2012 < pixels2002;

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

